define([],function(){const init=function(){document.addEventListener("keydown",function(event){if(event.altKey&&event.key==="ArrowLeft"){const previous=document.querySelector(".bookflow-chapter-navigation a:first-child");if(previous){previous.click()}}if(event.altKey&&event.key==="ArrowRight"){const links=document.querySelectorAll(".bookflow-chapter-navigation a");const next=links.length?links[links.length-1]:null;if(next){next.click()}}});if(window.location.hash){const target=document.querySelector(window.location.hash);if(target){target.focus({preventScroll:true});target.scrollIntoView({behavior:"smooth",block:"start"})}}};return{init:init}});